(window.RECIPE=window.RECIPE||{}).es={
title:"Receta: tu Instagram con Claude",
meta:["⏱ 40 min aprox.", "👩‍🍳 Sin saber programar", "💳 Requiere Claude Code (plan de pago de Claude)", "🍽 Resultado: tu voz, tu perfil afinado y tu primera publicación lista"],
ing:"Ingredientes",
q:"¿Qué quieres preparar primero?",
ph:"Cuenta de qué va tu cuenta y qué quieres publicar. Ejemplo: un reel que explique en 30 segundos cómo preparo pan de masa madre en casa",
yn:"¿Ya tienes publicaciones o reels tuyos?",
yntip:"Si tienes al menos tres, elige «Sí»: Claude aprenderá tu voz a partir de ellos, que funciona mejor que describirla.",
fin:"Ya tienes tu voz guardada, tu perfil afinado y tu primera publicación lista. Claude escribe; tú decides y publicas. Repite el plan cada semana y, cuando tengas datos, revísalos con /ig-audit.",
R:{key:"receta-instagram",def:"reel",empty:"[cuenta aquí tu idea, arriba]",
apps:{
 reel:{n:"Un reel",db:true,c:"reel",d:"un reel de 30 segundos que explique algo útil de mi tema y enganche en el primer segundo"},
 carrusel:{n:"Un carrusel",db:true,c:"carousel",d:"un carrusel de 7 diapositivas con consejos prácticos de mi tema"},
 perfil:{n:"Mejorar mi perfil",db:true,c:"profile",d:"revisar mi perfil y reescribir la biografía para que se entienda en 3 segundos a qué me dedico"},
 plan:{n:"Plan de la semana",db:true,c:"plan",d:"un plan de publicaciones para esta semana con formatos y horarios"},
 historias:{n:"Historias del día",db:true,c:"story",d:"una secuencia de historias para hoy que lleve a la gente a escribirme por mensaje"},
 otra:{n:"✏️ Otra idea",db:true,c:"reel",d:""}
},
ing:()=>`<li><b>Claude Code</b>: el cocinero, en la terminal de tu ordenador. Si aún no lo tienes, sigue el paso 1 de la <a href="../plugin.html">página del plugin de AMRI</a>.</li><li><b>Plugin Instagram Agent</b>: 13 recetas de Instagram para Claude, gratis y open source (licencia MIT), creado por <a href="https://github.com/Jakeschincariol/instagram-agent-skill" target="_blank" rel="noopener">Jake Schincariol</a>.</li><li><b>Tu cuenta de Instagram</b>: mejor si es profesional (de creador o de empresa), para ver tus estadísticas.</li><li><b>Tres publicaciones tuyas</b>, si ya tienes: los textos o guiones que más suenan a ti.</li>`,
steps:[
{t:"Prepara la cocina",s:"5 min · antes de empezar",b:()=>`<p class="what">Este plugin <b>no publica nada por ti</b> ni te pide la contraseña de Instagram. Claude escribe y tú decides qué publicas. Así cumples las normas de Instagram y no arriesgas tu cuenta.</p><h3>Pasos</h3><ol>
<li>Comprueba que tienes Claude Code: abre la Terminal, escribe <code>claude</code> y pulsa Intro.</li>
<li>En Instagram ve a <b>Configuración → Tipo de cuenta y herramientas</b> y cambia a <b>cuenta profesional</b> si aún no lo es. Es gratis.</li></ol>${ok("Claude Code se abre en tu terminal y tu cuenta de Instagram es profesional.")}`},
{t:"Instala el plugin de Instagram",s:"2 min · dos comandos",b:()=>`<p class="what">Un plugin añade recetas nuevas a Claude Code. Este trae 13, todas empiezan por <code>/ig-</code>.</p><h3>Pasos</h3><ol><li>Dentro de Claude Code, pega este comando:</li></ol>${cb("/plugin marketplace add Jakeschincariol/instagram-agent-skill")}<ol start="2"><li>Y después este:</li></ol>${cb("/plugin install instagram-agent")}
${tip("Antes de instalar un plugin de otra persona, echa un vistazo a su repositorio: este es open source y no se conecta a internet ni sube tus datos.")}${ok("al escribir <code>/ig</code> aparecen las recetas, como <code>/ig-reel</code> o <code>/ig-caption</code>.")}`},
{t:"Enséñale tu voz",s:"10 min · el paso más importante",b:()=>`<p class="what">Todas las recetas del plugin leen un archivo llamado <b>voice.md</b>: quién eres, a quién hablas, cómo suenas y qué no dirías nunca. En Instagram importa mucho porque tienes que decir las frases en voz alta.</p><h3>Si ya tienes publicaciones</h3><ol><li>Pega en Claude Code este mensaje y, debajo, tres textos o guiones tuyos:</li></ol>${cb("Escribe mi voice.md a partir de estos tres textos míos y guárdalo en ~/.claude/instagram/voice.md. Escribo siempre en español. Pregúntame lo que no puedas deducir: a quién hablo, qué ofrezco y qué temas no toco.\n\n1. [pega aquí tu primer texto]\n2. [pega aquí el segundo]\n3. [pega aquí el tercero]")}<h3>Si todavía no tienes</h3><ol><li>Pega en Claude Code este mensaje:</li></ol>${cb(`Ayúdame a escribir mi voice.md para Instagram y guárdalo en ~/.claude/instagram/voice.md. Mi cuenta va de ${D()}. Escribo siempre en español. Hazme las preguntas de una en una.`)}
${det("¿Qué lleva un buen voice.md?",["<b>A quién hablas</b>, muy concreto: «panaderos caseros que empiezan», no «gente».","<b>Palabras que usas</b> y palabras que nunca dirías.","<b>Tus opiniones</b>: tres ideas en las que crees y otros no. De ahí salen los mejores reels.","<b>Pruebas reales</b>: datos y resultados tuyos. El plugin nunca se inventa números; si faltan, deja huecos como {{tu número}}."])}
${ok("existe el archivo <code>~/.claude/instagram/voice.md</code> y, al leerlo, suena a ti.")}`},
{t:"Revisa tu perfil",s:"5 min · primera impresión",b:()=>`<p class="what">Tu perfil es tu escaparate: en tres segundos alguien decide si te sigue. Claude lo puntúa sobre 100 con 12 criterios y te propone una biografía nueva.</p>${cb("/ig-profile")}
${tip("Pega tu biografía actual, tu nombre y el enlace que tienes cuando te lo pida.")}${ok("tienes tu puntuación y has cambiado la biografía en Instagram.")}`},
{t:"Prepara tu primera publicación",s:"10 min · el plato principal",b:()=>`<p class="what">Le das la idea y Claude prepara la publicación. Para un reel, propone tres ganchos para el primer segundo, los puntúa y escribe el guion.</p>${cb(`/ig-${(APPS[app]&&APPS[app].c)||"reel"} ${D()}`)}
${tip("Elige el gancho que dirías tú en voz alta. Si ninguno te convence, pídele otros tres.")}${ok("tienes el guion o las diapositivas listos para grabar o diseñar.")}`},
{t:"Que suene a ti",s:"2 min · quitar el tono de IA",b:()=>`<p class="what">Esta receta limpia el texto: quita frases hechas, signos raros y ese tono de «escrito por IA», y le da una puntuación de naturalidad.</p>${cb("/ig-human [pega aquí tu guion o tu texto]")}${ok("al leerlo en voz alta, suena a ti.")}`},
{t:"Escribe el texto del post",s:"3 min · el pie de foto",b:()=>`<p class="what">Instagram solo muestra unos 125 caracteres antes del «más». Esta receta te enseña exactamente qué se verá y limita las etiquetas a cinco.</p>${cb("/ig-caption")}${ok("la primera línea se entiende sola y tienes como mucho cinco etiquetas.")}`},
{t:"Planifica la semana",s:"5 min · constancia",b:()=>`<p class="what">Publicar con constancia importa más que publicar mucho. Claude te propone qué publicar cada día, en qué formato y a qué hora, y diez cuentas con las que interactuar.</p>${cb("/ig-plan")}${tip("Guarda el plan en tu calendario. Si tienes la receta «Tu secretaría: Gmail y Calendar», Claude puede crear los recordatorios por ti.")}${ok("tienes el plan de la semana apuntado.")}`},
{t:"Publica tú y mide",s:"Una semana · aprender",b:()=>`<p class="what">Publica desde la app de Instagram, como siempre. Pasada una semana, mira qué funcionó con tus datos reales.</p><ol><li>Publica tu primera pieza.</li><li>A los 7 días, abre las estadísticas de Instagram y copia el alcance, los guardados y los compartidos de cada publicación.</li><li>Pégalos aquí:</li></ol>${cb("/ig-audit [pega aquí tus números de la semana]")}${ok("sabes qué publicación funcionó mejor y por qué, y qué repetir la semana que viene.")}`},
{x:1,t:"Convierte un contenido en una semana",s:"Opcional · reutilizar",b:()=>`<p class="what">Un vídeo largo, un pódcast o una newsletter se convierten en varios reels y carruseles independientes.</p>${cb("/ig-repurpose [pega el texto o la transcripción]")}`},
{x:1,t:"Cuida tu comunidad",s:"Opcional · comentarios y mensajes",b:()=>`<ul><li><code>/ig-comment</code>: comentarios con sentido para las cuentas de tu sector.</li><li><code>/ig-reply</code>: respuestas a los comentarios de tus publicaciones.</li><li><code>/ig-dm</code>: primer mensaje, propuesta de colaboración y seguimiento.</li></ul>${tip("Revisa siempre cada mensaje antes de enviarlo: los envías tú.")}`},
{x:1,t:"Descubre qué funciona en tu tema",s:"Opcional · investigar",b:()=>`<p class="what">Busca las publicaciones que destacan en tu tema y explica qué fórmula usan. Lee como lo harías tú, desde tu navegador; no descarga datos de forma automática.</p>${cb("/ig-viral [tu tema]")}`}
]}};
